// New Rocker (titles, numbers) + Alegreya Sans Bold (descriptions), SIL Open Font License 1.1 (via @fontsource).
const F_TITLE = 'StzTitle', F_BODY = 'StzBody';
const STZ_FONTS_READY = Promise.all([
  new FontFace(F_TITLE, 'url(data:font/woff2;base64,)').load().then(f => document.fonts.add(f)),
  new FontFace(F_BODY, 'url(data:font/woff2;base64,)').load().then(f => document.fonts.add(f)),
]).catch(e => console.error('font', e));
